const $ = id => document.getElementById(id);
const clone = value => JSON.parse(JSON.stringify(value));
const uid = () => crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(36) + Math.random().toString(36).slice(2);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const raw = (name, body, extra = {}) => ({id:uid(),name,mode:'raw',status:200,contentType:'application/json',delay:0,code:JSON.stringify(body,null,2),scriptCode:'function main(request, mock) {\n  return {\n    status: 200,\n    body: { code: "0000", data: request.body, requestId: mock.uuid() }\n  };\n}',field:'body.orderId',operator:'eq',value:'1001',priority:100,...extra});
const makeEndpoint = (name,path,method,rules) => {const config={name,path,method,enabled:true,rules};return{id:uid(),draft:config,published:clone(config),history:[{version:1,time:new Date().toLocaleString(),config:clone(config)}]};};
const seed = () => ({projects:[{id:'erp',name:'ERP 系统',slug:'erp',endpoints:[makeEndpoint('查询生产订单','/api/orders/query','POST',[raw('订单查询成功',{code:'0000',message:'查询成功',data:{orderId:'1001',materialCode:'MAT-2026-001',quantity:120,status:'RELEASED'}},{priority:100}),raw('订单不存在',{code:'1004',message:'订单不存在',data:null},{value:'1002',priority:90}),raw('默认响应',{code:'0000',message:'成功',data:null},{default:true,priority:0})]),makeEndpoint('提交报工结果','/api/production/report','POST',[raw('默认响应',{success:true,message:'报工已接收'},{default:true})]),makeEndpoint('查询物料信息','/api/materials/{materialId}','GET',[raw('动态物料信息',{}, {default:true,mode:'script',code:'function main(request, mock) {\n  return {\n    status: 200,\n    headers: { "Content-Type": "application/json" },\n    body: {\n      code: "0000",\n      data: {\n        materialId: request.pathParams.materialId,\n        stock: mock.randomInt(100, 500),\n        updatedAt: mock.now()\n      }\n    }\n  };\n}'})])]},{id:'wms',name:'WMS 仓储系统',slug:'wms',endpoints:[makeEndpoint('查询库存','/api/inventory/query','POST',[raw('库存充足',{code:200,data:{warehouse:'A01',available:850}},{default:true})])]}],logs:[]});
let state;try{state=JSON.parse(localStorage.getItem('mocklab-prototype-v1'))}catch{}if(!state?.projects?.length)state=seed();
let projectId=state.projects[0].id,endpointId=state.projects[0].endpoints[0].id,working,ruleId,tab='response',view='editor',dirty=false,dialogKind='endpoint',busy=false;
const project=()=>state.projects.find(p=>p.id===projectId), endpoint=()=>project().endpoints.find(e=>e.id===endpointId), rule=()=>working.rules.find(r=>r.id===ruleId);
function persist(){try{localStorage.setItem('mocklab-prototype-v1',JSON.stringify(state));return true}catch{toast('浏览器存储不可用或已满，本次内容未持久保存');return false}}
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),4200)}
function markDirty(){dirty=true;$('dirty').textContent='未保存';updateUrl()}
function updateUrl(){$('url').textContent=`http://mock.company.local/m/${project().slug}${working.path}`}
function capture(){if(!working)return;working.method=$('method').value;working.path=$('path').value;working.enabled=$('enabled').checked;const r=rule();if(!r)return;r.name=$('ruleName').value;r.mode=document.querySelector('[data-mode].selected')?.dataset.mode||r.mode;r.status=Number($('status').value);r.contentType=$('contentType').value;r.delay=Number($('delay').value);r.code=$('code').value;r.field=$('field').value;r.operator=$('operator').value;r.value=$('value').value;r.priority=Number($('priority').value)}
function saveDraft(silent=false){capture();endpoint().draft=clone(working);const saved=persist();dirty=!saved;$('dirty').textContent=saved?'已保存':'未保存';renderList();if(!silent&&saved)toast('草稿已保存在当前浏览器');return saved}
function switchEndpoint(id){if(working&&dirty)saveDraft(true);endpointId=id;working=clone(endpoint().draft);ruleId=working.rules[0].id;dirty=false;renderEditor();renderList();}
function renderOverview(){const p=project();$('project').innerHTML=state.projects.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');$('project').value=p.id;$('crumb').textContent=p.name;$('total').textContent=p.endpoints.length;$('navCount').textContent=p.endpoints.length;$('publishedCount').textContent=p.endpoints.filter(e=>e.published?.enabled).length;$('ruleCount').textContent=p.endpoints.reduce((n,e)=>n+e.draft.rules.length,0);renderList()}
function renderList(){const search=$('search').value.toLowerCase();$('listCount').textContent=project().endpoints.length;$('endpoints').innerHTML=project().endpoints.filter(e=>(e.draft.name+e.draft.path).toLowerCase().includes(search)).map(e=>`<button class="endpoint ${e.id===endpointId?'selected':''}" data-endpoint="${e.id}"><span class="ep-name">${esc(e.draft.name)}</span><span class="ep-path"><b class="method-tag ${e.draft.method.toLowerCase()}">${esc(e.draft.method)}</b>${esc(e.draft.path)}</span>${e.published?.enabled?'<span class="dot"></span>':''}</button>`).join('')||'<div class="empty">没有匹配的接口</div>'}
function renderEditor(){$('endpointTitle').textContent=working.name;$('endpointMeta').textContent=endpoint().published?`已模拟发布 v${endpoint().history.length} · ${project().name}`:'尚未模拟发布';$('method').value=working.method;$('path').value=working.path;$('enabled').checked=working.enabled;$('dirty').textContent=dirty?'未保存':'已保存';updateUrl();renderRules();renderRule();$('requestPath').value=working.path.replace(/\{[^}]+\}/g,'1001');$('resultMeta').textContent='等待请求';$('resultBody').textContent='点击「发送模拟请求」查看返回内容';$('resultHeaders').textContent='—';setTab(tab);renderHistory()}
function renderRules(){$('ruleList').innerHTML=[...working.rules].sort((a,b)=>(a.default?1:0)-(b.default?1:0)||b.priority-a.priority).map(r=>`<button class="rule-button ${r.id===ruleId?'selected':''}" data-rule="${r.id}"><span>${esc(r.name)}</span><small>${r.default?'兜底':r.priority}</small></button>`).join('')}
function renderRule(){const r=rule();$('ruleName').value=r.name;$('field').value=r.field;$('operator').value=r.operator;$('value').value=r.value;$('priority').value=r.priority;$('status').value=r.status;$('contentType').value=r.contentType;$('delay').value=r.delay;$('code').value=r.code;$('conditionBox').classList.toggle('hidden',!!r.default);$('defaultBox').classList.toggle('hidden',!r.default);$('deleteRule').classList.toggle('hidden',!!r.default);document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===r.mode));const script=r.mode==='script';$('editorLanguage').textContent=script?'JAVASCRIPT':'JSON / TEXT';$('fileLabel').textContent=script?'response.js':'response.txt';$('format').classList.toggle('hidden',script);$('codeHint').textContent=script?'main(request, mock) → { status, headers, body }':'原样返回，不增加统一响应包装'}
function setTab(name){tab=name;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===name));['response','debug','history'].forEach(n=>$(n+'Tab').classList.toggle('hidden',n!==name));if(name==='history')renderHistory()}
function setView(name){view=name;['editor','logs','guide'].forEach(n=>$(n+'View').classList.toggle('hidden',n!==name));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='logs')renderLogs()}
function validate(){capture();if(!/^\/(?:[^\s?#]*)$/.test(working.path))throw Error('接口路径必须以 / 开头，不能包含空格、Query 或 #');const shape=p=>p.replace(/\{[^}]+\}/g,'{}');if(project().endpoints.some(e=>e.id!==endpointId&&[e.draft,e.published].some(c=>c&&c.method===working.method&&shape(c.path)===shape(working.path))))throw Error('同系统中已存在相同或冲突的接口路径');if(working.rules.some(r=>!r.name.trim()))throw Error('请填写场景名称');const ps=working.rules.filter(r=>!r.default).map(r=>r.priority);if(new Set(ps).size!==ps.length)throw Error('条件场景优先级不能重复');for(const r of working.rules){if(!Number.isInteger(r.status)||r.status<200||r.status>599)throw Error('HTTP 状态码须为 200～599 的整数');if(!Number.isFinite(r.delay)||r.delay<0||r.delay>3000)throw Error('原型响应延迟为 0～3000ms');if(!r.default&&!/^(body|query|headers|pathParams)\.[\w.-]+$/.test(r.field))throw Error('条件字段须以 body.、query.、headers. 或 pathParams. 开头');if(r.mode==='script'&&!/\bfunction\s+main\s*\(/.test(r.code))throw Error('脚本请定义 function main(request, mock)') }}
function renderHistory(){$('historyList').innerHTML=[...endpoint().history].reverse().map(h=>`<div class="history-item"><b>v${h.version}</b><div>${esc(h.version===endpoint().history.length?'当前版本':'历史版本')}<small>${esc(h.time)} · ${h.config.rules.length} 个场景</small></div>${h.version===endpoint().history.length?'':`<button data-rollback="${h.version}">回滚到此版本</button>`}</div>`).join('')||'<div class="empty">还没有发布记录，先完成一次模拟发布</div>'}
function renderLogs(){$('logsList').innerHTML=state.logs.map(l=>`<div class="log-row"><span>${esc(l.time)}</span><div><b>${esc(l.project)}</b><br><code>${esc(l.method)} ${esc(l.path)}</code></div><span>${l.status} · ${l.duration} ms</span><span>${esc(l.rule)}<br><small>${esc(l.source)}</small></span></div>`).join('')||'<div class="empty">尚无调试记录，发送一次模拟请求后会显示在这里</div>'}
function pathParams(template,path){const t=template.split('/'),p=path.split('/');if(t.length!==p.length)return null;const out={};for(let i=0;i<t.length;i++){const match=t[i].match(/^\{(\w+)\}$/);if(match){if(!p[i])return null;out[match[1]]=decodeURIComponent(p[i])}else if(t[i]!==p[i])return null}return out}
function matchRule(r,req){if(r.default)return true;const val=r.field.split('.').reduce((v,k)=>v!=null?Object.prototype.hasOwnProperty.call(Object(v),k)?v[k]:undefined:undefined,req);if(r.operator==='exists')return val!==undefined;if(r.operator==='ne')return val!==undefined&&String(val)!==r.value;if(r.operator==='contains')return val!==undefined&&String(val).includes(r.value);return val!==undefined&&String(val)===r.value}
function runScript(code,request){return new Promise((resolve,reject)=>{const frame=document.createElement('iframe');frame.hidden=true;frame.setAttribute('sandbox','allow-scripts');let done=false;const cleanup=()=>{done=true;clearTimeout(watch);window.removeEventListener('message',listener);frame.remove()};const listener=e=>{if(e.source!==frame.contentWindow||done)return;if(e.data?.ready){frame.contentWindow.postMessage({code,request},'*');return}cleanup();e.data?.error?reject(Error(e.data.error)):resolve(e.data.result)};window.addEventListener('message',listener);const watch=setTimeout(()=>{cleanup();reject(Error('脚本执行超时（1 秒）'))},2500);frame.srcdoc=`<!doctype html><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline' 'unsafe-eval' blob:; worker-src blob:; connect-src 'none';"><script>onmessage = function(e) { const data=e.data; const src='onmessage = async function(e) { try { const mock={uuid:()=>crypto.randomUUID(),now:()=>new Date().toISOString(),randomInt:(a,b)=>Math.floor(Math.random()*(b-a+1))+a}; const fn=new Function("request", "mock", e.data.code+String.fromCharCode(10)+";return main(request,mock)"); const result=await fn(e.data.request,mock); const json=JSON.stringify(result); if(!json || json.length>2097152)throw Error("响应为空或超过 2MB"); postMessage({result:JSON.parse(json)}); } catch(err) {postMessage({error:err.message})} }'; const url=URL.createObjectURL(new Blob([src],{type:'text/javascript'})); const worker=new Worker(url); const timer=setTimeout(()=>{worker.terminate();parent.postMessage({error:'脚本执行超时（1 秒）'},'*')},1000); worker.onmessage=e=>{clearTimeout(timer);worker.terminate();URL.revokeObjectURL(url);parent.postMessage(e.data,'*')}; worker.onerror=e=>{clearTimeout(timer);worker.terminate();parent.postMessage({error:e.message||'脚本执行失败'},'*')};worker.postMessage(data); };parent.postMessage({ready:true},'*');<\/script>`;document.body.append(frame)})}
function parseObject(text,name){const v=JSON.parse(text);if(!v||typeof v!=='object'||Array.isArray(v))throw Error(name+'必须是 JSON 对象');return v}
async function debug(){if(busy)return;capture();const target=clone($('debugSource').value==='draft'?working:endpoint().published);if(!target){toast('当前接口尚未模拟发布');return}let request;try{const headers=parseObject($('headers').value,'Headers');request={method:target.method,path:$('requestPath').value,query:parseObject($('query').value,'Query'),headers:Object.fromEntries(Object.entries(headers).map(([k,v])=>[k.toLowerCase(),v])),body:JSON.parse($('requestBody').value),rawBody:$('requestBody').value};request.pathParams=pathParams(target.path,request.path)}catch(e){toast('请求格式错误：'+e.message);return}const pName=project().name,source=$('debugSource').selectedOptions[0].textContent;busy=true;$('run').disabled=true;$('run').textContent='请求中…';const start=performance.now();let result,chosen;try{if(!target.enabled)result={status:404,body:'接口已停用'};else if(!request.pathParams)result={status:404,body:'请求路径未匹配当前接口'};else{chosen=[...target.rules].sort((a,b)=>(a.default?1:0)-(b.default?1:0)||b.priority-a.priority).find(r=>matchRule(r,request));if(!chosen)throw Error('没有可用的默认响应');if(chosen.mode==='script'){result=await runScript(chosen.code,request);if(!result||typeof result!=='object'||Array.isArray(result))throw Error('脚本必须返回 { status, headers, body }');result.status??=chosen.status;result.headers={"Content-Type":chosen.contentType,...result.headers}}else result={status:chosen.status,headers:{"Content-Type":chosen.contentType},body:chosen.code};if(!Number.isInteger(result.status)||result.status<200||result.status>599)throw Error('脚本返回了无效 HTTP 状态码');await new Promise(r=>setTimeout(r,Math.min(3000,Math.max(0,chosen.delay))))}}catch(e){result={status:e.message.includes('超时')?504:500,body:{error:e.message}}}finally{busy=false;$('run').disabled=false;$('run').textContent='▶ 发送模拟请求'}const duration=Math.round(performance.now()-start);$('resultMeta').textContent=`${result.status} · ${duration} ms · ${chosen?.name||'未命中'} · ${source}`;$('resultBody').textContent=[204,304].includes(result.status)?'':typeof result.body==='string'?result.body:JSON.stringify(result.body??null,null,2);$('resultHeaders').textContent=JSON.stringify(result.headers||{},null,2);$('lastStatus').textContent=result.status;$('lastTime').textContent=`${duration} ms · ${chosen?.name||'未命中'}`;state.logs.unshift({time:new Date().toLocaleString(),project:pName,method:target.method,path:request.path,status:result.status,duration,rule:chosen?.name||'未命中',source});state.logs=state.logs.slice(0,50);persist()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.endpoint)switchEndpoint(b.dataset.endpoint);if(b.dataset.rule){capture();ruleId=b.dataset.rule;renderRules();renderRule()}if(b.dataset.tab){capture();setTab(b.dataset.tab)}if(b.dataset.view)setView(b.dataset.view);if(b.dataset.mode){capture();const r=rule();if(r.mode===b.dataset.mode)return;if(r.mode==='raw')r.rawCode=r.code;else r.scriptCode=r.code;r.mode=b.dataset.mode;r.code=r.mode==='raw'?(r.rawCode||'{\n  "code": "0000",\n  "message": "成功"\n}'):(r.scriptCode||raw('',{}).scriptCode);markDirty();renderRule()}if(b.dataset.rollback){const h=endpoint().history.find(h=>h.version===Number(b.dataset.rollback));const c=clone(h.config);endpoint().published=c;endpoint().history.push({version:endpoint().history.length+1,time:new Date().toLocaleString(),config:clone(c)});persist();renderHistory();$('endpointMeta').textContent=`已模拟发布 v${endpoint().history.length} · ${project().name}`;toast('已回滚发布配置，当前草稿保持不变');renderOverview()}});
['method','path','enabled','ruleName','field','operator','value','priority','status','contentType','delay','code'].forEach(id=>$(id).addEventListener('input',()=>{capture();markDirty();if(['ruleName','priority'].includes(id))renderRules()}));
$('search').oninput=renderList;$('project').onchange=e=>{if(dirty)saveDraft(true);projectId=e.target.value;working=null;$('search').value='';switchEndpoint(project().endpoints[0].id);renderOverview()};$('save').onclick=()=>{saveDraft();renderOverview()};$('publish').onclick=()=>{try{validate();if(!saveDraft(true))return;endpoint().published=clone(working);endpoint().history.push({version:endpoint().history.length+1,time:new Date().toLocaleString(),config:clone(working)});persist();renderEditor();renderOverview();toast('模拟发布成功，已发布版本可用于本地调试')}catch(e){toast(e.message)}};$('goDebug').onclick=()=>{capture();setTab('debug')};$('run').onclick=debug;
$('addRule').onclick=()=>{capture();const p=Math.max(0,...working.rules.filter(r=>!r.default).map(r=>r.priority))+10;const r=raw('新响应场景',{code:'0000',message:'自定义响应'},{priority:p});working.rules.push(r);ruleId=r.id;markDirty();renderRules();renderRule()};$('deleteRule').onclick=()=>{if(rule().default)return;working.rules=working.rules.filter(r=>r.id!==ruleId);ruleId=working.rules[0].id;markDirty();renderRules();renderRule();toast('场景已从草稿移除，发布后生效')};$('format').onclick=()=>{try{$('code').value=JSON.stringify(JSON.parse($('code').value),null,2);capture();markDirty()}catch{toast('内容不是合法 JSON，XML 或文本报文无需格式化')}};$('copyUrl').onclick=async()=>{try{await navigator.clipboard.writeText($('url').textContent);toast('已复制示例地址；原型尚未提供真实 HTTP 接口')}catch{toast('无法访问剪贴板，请选中示例地址手动复制')}};
function showCreate(kind){dialogKind=kind;$('dialogTitle').textContent=kind==='project'?'添加第三方系统':'新建接口';$('createKeyLabel').textContent=kind==='project'?'系统标识（英文、数字、短横线）':'接口路径';$('createName').value='';$('createKey').value='';$('createKey').placeholder=kind==='project'?'例如：sap-erp':'/api/orders/query';$('createHint').textContent=kind==='project'?'创建后预置一个健康检查接口，方便开始体验。':'新接口默认使用 POST，可在配置页修改。';$('createDialog').showModal()}
$('newEndpoint').onclick=()=>showCreate('endpoint');$('addProject').onclick=()=>showCreate('project');$('closeDialog').onclick=$('cancelDialog').onclick=()=>$('createDialog').close();$('createForm').onsubmit=e=>{e.preventDefault();const name=$('createName').value.trim(),key=$('createKey').value.trim();if(!name){toast('请填写名称');return}if(dialogKind==='project'){if(!/^[a-z][a-z0-9-]{0,39}$/.test(key)){toast('系统标识以小写字母开头，仅包含小写字母、数字和短横线');return}if(state.projects.some(p=>p.slug===key)){toast('该系统标识已存在');return}if(dirty)saveDraft(true);const ep=makeEndpoint('健康检查','/health','GET',[raw('默认响应',{status:'ok'},{default:true})]);ep.published=null;ep.history=[];const p={id:uid(),name,slug:key,endpoints:[ep]};state.projects.push(p);projectId=p.id;working=null;switchEndpoint(ep.id)}else{if(!/^\/[^\s?#]*$/.test(key)){toast('请输入以 / 开头的接口路径');return}if(project().endpoints.some(e=>e.draft.path===key&&e.draft.method==='POST')){toast('该 POST 接口已存在');return}if(dirty)saveDraft(true);const ep=makeEndpoint(name,key,'POST',[raw('默认响应',{code:'0000',message:'成功'},{default:true})]);ep.published=null;ep.history=[];project().endpoints.push(ep);working=null;switchEndpoint(ep.id)}persist();renderOverview();setView('editor');setTab('response');$('createDialog').close();toast('创建成功，可以开始配置响应')};
window.addEventListener('beforeunload',()=>{if(dirty)saveDraft(true)});
switchEndpoint(endpointId);renderOverview();
